import json,sqlite3,tempfile,unittest
from pathlib import Path
from pagleba.common import RANKS,write_tsv,read_tsv
from pagleba.config import initialize,load
from pagleba.functions import run_functions
from pagleba.ncbi import prepare
from pagleba.macadam import import_macadam

class FunctionalContext(unittest.TestCase):
    def test_fungaltrait_homonym_not_transferred_to_plant_but_oomycete_context_supported(self):
        with tempfile.TemporaryDirectory() as temp:
            root=Path(temp);cfg=load(initialize(root/'project','18s'));table=root/'counts.tsv';base=dict(Feature='plant',**dict(zip(RANKS,['Eukaryota','Viridiplantae','Tracheophyta','C','O','FamilyX','GenusX',''])),sample01=10);oom=dict(base,Feature='oomycete',Kingdom='Stramenopiles',Phylum='Oomycota');write_tsv(table,list(base),[base,oom]);ann=root/'ann.tsv';a=dict(Source='FungalTraits',Rank='Genus',Taxon='GenusX',Trait='pathotroph',Weight=1,Evidence='fixture',ContextFamily='FamilyX',ContextPhylum='Oomycota');write_tsv(ann,list(a),[a]);cfg['functions']=[dict(id='traits',marker='ssu',annotations=str(ann),method='long')];result=run_functions(cfg,[('ssu',table)]);counts=read_tsv(result[0][1].with_name('trait_counts.tsv'));self.assertEqual(float(counts[0]['sample01']),10);evidence=read_tsv(result[0][1].with_name('feature_trait_evidence.tsv'));self.assertEqual({r['Feature'] for r in evidence},{'oomycete'})
    def test_macadam_complete_pathway_and_prevalence_gates(self):
        with tempfile.TemporaryDirectory() as temp:
            root=Path(temp);nodes=root/'nodes';names=root/'names';taxa=[(1,1,'no rank','root'),(2,1,'domain','Bacteria'),(20,2,'family','FamilyX'),(10,20,'genus','GenusA'),(11,20,'genus','GenusB'),(100,10,'species','GenusA species1'),(101,10,'species','GenusA species2'),(102,11,'species','GenusB species1')];nodes.write_text(''.join(f'{tid}\t|\t{parent}\t|\t{rank}\t|\n' for tid,parent,rank,name in taxa));names.write_text(''.join(f'{tid}\t|\t{name}\t|\t\t|\tscientific name\t|\n' for tid,parent,rank,name in taxa));ncbi=root/'ncbi.sqlite';prepare(nodes,names,ncbi);db=root/'macadam.sqlite';c=sqlite3.connect(db);c.executescript('CREATE TABLE taxonomy(x);CREATE TABLE faprotax(taxID INTEGER,pathwayName TEXT);CREATE TABLE IJSEMPhenoDB(taxID INTEGER,strainName TEXT,pathway TEXT);CREATE TABLE pathway(ID TEXT,taxonomy TEXT,pathwayFrameID TEXT,pathwayScore REAL);');c.execute("INSERT INTO faprotax VALUES(10,'explicit_function')");c.execute("INSERT INTO IJSEMPhenoDB VALUES(100,'strainX','gelatinase')");c.executemany('INSERT INTO pathway VALUES(?,?,?,?)',[('100.a','.1.2.20.10.100.','PWY_TEST',1),('101.a','.1.2.20.10.101.','PWY_TEST',.5),('102.a','.1.2.20.11.102.','OTHER',1)]);c.commit();c.close();rules=root/'rules.json';rules.write_text(json.dumps({'traits':{'trait1':{'pathway_ids':['PWY_TEST']}},'pathway_score_min':.999999,'genus_positive_reference_fraction_min':1/3,'higher_rank_positive_reference_fraction_min':.9,'higher_rank_min_genomes':5,'higher_rank_min_genera':3}));out=root/'annotations.tsv';import_macadam(db,ncbi,rules,out);rows=read_tsv(out);met=[r for r in rows if r['Source']=='MACADAM_MetaCyc'];self.assertEqual([(r['Rank'],r['Taxon']) for r in met],[('Genus','GenusA')]);self.assertTrue(any(r['Source']=='MACADAM_IJSEM' and r['Taxon']=='GenusA' for r in rows));evidence=read_tsv(str(out)+'.evidence.tsv');a=next(r for r in evidence if r['Taxon']=='GenusA');self.assertEqual(a['Positive_Genomes'],'1');self.assertEqual(a['Reference_Genomes'],'2')
